import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import { setTimeout as sleep } from 'node:timers/promises';
import { fileURLToPath } from 'node:url';
import { createIsolatedAcquirer } from '../wsc-phase2b/isolated-acquirer.mjs';
import { evaluate, render } from '../wsc-vs1/engine.mjs';
import { collectMailDns, createRestrictedNetworkProbe, withDnsDeadline } from './restricted-network-probe.mjs';
import { createTestConnectionAdapter } from './test-connection-adapter.mjs';

const root = path.dirname(fileURLToPath(import.meta.url)); const url = 'https://example-protected.test/'; const resolve = () => ['93.184.216.34'];
const fixture = JSON.parse(fs.readFileSync(path.join(root, '..', 'wsc-vs1', 'fixtures', 'synthetic-protected.json'), 'utf8'));
const diagnosis = () => ({ ...structuredClone(fixture), targetUrl: url, mailDomain: null, checkedAt: '2026-10-26T00:00:00.000Z' });
const disabled = createRestrictedNetworkProbe();
await assert.rejects(() => disabled({ url, addresses: resolve(), mailDomain: null }), /EXTERNAL_NETWORK_DISABLED_PENDING_APPROVAL/);
const grants = new Map([['single', { targetUrl: url, expiresAt: 2_000 }]]);
const approvalStore = { consume: ({ approvalId, url: requested, now }) => { const grant = grants.get(approvalId); if (!grant || grant.targetUrl !== requested || grant.expiresAt <= now) return null; grants.delete(approvalId); return grant; } };
let networkRequest; const restricted = createRestrictedNetworkProbe({ approvalStore, clock: () => 1_000, lookup: async () => [{ address: '93.184.216.34' }], networkExchange: async input => { networkRequest = input; return { remoteAddress: input.ip, responseBytes: 2, bodyChunks: ['ok'], diagnosis: diagnosis() }; } });
const restrictedResult = await restricted({ url, addresses: resolve(), mailDomain: null, approvalId: 'single' });
assert.equal(restrictedResult.remoteAddress, '93.184.216.34'); assert.equal(networkRequest.connection.host, '93.184.216.34'); assert.equal(networkRequest.connection.servername, 'example-protected.test'); assert.equal(networkRequest.connection.hostHeader, 'example-protected.test'); assert.equal(networkRequest.connection.rejectUnauthorized, true);
await assert.rejects(() => restricted({ url, addresses: resolve(), approvalId: 'single' }), /EXTERNAL_NETWORK_DISABLED_PENDING_APPROVAL/, 'used grant is rejected before DNS');
await assert.rejects(() => createRestrictedNetworkProbe({ approvalStore: { consume: () => ({ targetUrl: url, expiresAt: 999 }) }, clock: () => 1_000, lookup: async () => { throw new Error('DNS must not run'); } })({ url, addresses: resolve(), approvalId: 'expired' }), /EXTERNAL_NETWORK_DISABLED_PENDING_APPROVAL/);
let mismatchLookupCalled = false;
await assert.rejects(() => createRestrictedNetworkProbe({ approvalStore: { consume: () => ({ targetUrl: 'https://other.example/' , expiresAt: 2_000 }) }, clock: () => 1_000, lookup: async () => { mismatchLookupCalled = true; return []; } })({ url, addresses: resolve(), approvalId: 'wrong-target' }), /EXTERNAL_NETWORK_DISABLED_PENDING_APPROVAL/);
assert.equal(mismatchLookupCalled, false, 'target mismatch is rejected before DNS');
const records = await collectMailDns('mail.example', async name => name.startsWith('_dmarc') ? [['v=DMARC1; p=reject']] : [['v=spf1 -all']]);
assert.equal(records.spf.lookupStatus, 'FOUND'); assert.equal(records.dmarc.tags.p, 'reject');
const absent = await collectMailDns('mail.example', async () => []); assert.equal(absent.spf.lookupStatus, 'NO_RECORD'); assert.equal(absent.dmarc.lookupStatus, 'NO_RECORD');
const nxdomain = await collectMailDns('mail.example', async () => { throw Object.assign(new Error('not found'), { code: 'ENOTFOUND' }); }); assert.equal(nxdomain.spf.lookupStatus, 'NO_RECORD'); assert.equal(nxdomain.dmarc.lookupStatus, 'NO_RECORD');
const piraDns = await collectMailDns('pira.or.jp', async name => { if (name === '_dmarc.pira.or.jp') throw Object.assign(new Error('NXDOMAIN'), { code: 'ENOTFOUND' }); return [['v=spf1 a:www3859.sakura.ne.jp mx ~all']]; });
const piraReport = evaluate({ ...diagnosis(), mailDomain: 'pira.or.jp', dns: piraDns }, { rulesPath: path.join(root, '..', 'wsc-vs1', 'rules.json'), explanationsPath: path.join(root, '..', 'wsc-vs1', 'explanations.json') });
const piraHtml = render(piraReport, { name: 'PIRA相当テスト', url });
assert.ok(piraReport.findings.some(finding => finding.id === 'SPF_PRESENT')); assert.ok(piraReport.findings.some(finding => finding.id === 'DMARC_ABSENT')); assert.ok(piraHtml.includes('メールの送信元を示す設定があります')); assert.ok(piraHtml.includes('対象ドメインのDMARCレコードが存在しないというDNS応答でした。'));
const failure = await collectMailDns('mail.example', async () => { throw Object.assign(new Error('dns fail'), { code: 'ETIMEOUT' }); }); assert.equal(failure.spf.lookupStatus, 'UNVERIFIED');
const invalid = await collectMailDns('mail.example', async () => [['invalid']]); assert.equal(invalid.spf.error, 'RECORD_FORMAT_INVALID'); assert.equal(invalid.spf.lookupStatus, 'UNVERIFIED'); assert.equal(invalid.dmarc.lookupStatus, 'UNVERIFIED');
const invalidReport = evaluate({ ...diagnosis(), mailDomain: 'mail.example', dns: invalid }, { rulesPath: path.join(root, '..', 'wsc-vs1', 'rules.json'), explanationsPath: path.join(root, '..', 'wsc-vs1', 'explanations.json') });
assert.equal(invalidReport.findings.some(finding => finding.id === 'DMARC_ABSENT'), false, 'invalid DMARC is not absent'); assert.ok(invalidReport.internalOnly.some(item => item.startsWith('DMARC:')));
const invalidHtml = render(invalidReport, { name: '形式不正テスト株式会社', headOffice: '東京都', url }); assert.equal(invalidHtml.includes('対象ドメインのDMARCレコードが存在しないというDNS応答でした。'), false);
let delayedCompleted = false;
const timedOutTxt = await collectMailDns('mail.example', async () => { await sleep(30); delayedCompleted = true; return [['v=DMARC1; p=reject']]; }, { timeoutMs: 5 });
assert.equal(timedOutTxt.spf.lookupStatus, 'UNVERIFIED'); assert.equal(timedOutTxt.dmarc.lookupStatus, 'UNVERIFIED'); assert.equal(timedOutTxt.spf.error, 'DNS_ACQUISITION_TIMEOUT'); await sleep(35); assert.equal(delayedCompleted, true, 'late DNS completion is ignored after timeout');
const dnsAbort = new AbortController(); const abortedDns = withDnsDeadline(() => new Promise(() => {}), { timeoutMs: 100, signal: dnsAbort.signal }); dnsAbort.abort(); await assert.rejects(abortedDns, /DNS_ACQUISITION_ABORTED/);
await assert.rejects(() => createRestrictedNetworkProbe({ approvalStore: { consume: () => ({ targetUrl: url, expiresAt: 2_000 }) }, clock: () => 1_000, lookup: () => new Promise(() => {}), dnsTimeoutMs: 5 })({ url, addresses: resolve(), approvalId: 'lookup-timeout' }), /DNS_ACQUISITION_TIMEOUT/);
let request; const adapter = createTestConnectionAdapter(async input => { request = input; return { remoteAddress: '93.184.216.34', responseBytes: 2, bodyChunks: ['ok'], diagnosis: diagnosis() }; });
const acquire = createIsolatedAcquirer({ resolve, probe: adapter }); const result = await acquire({ url });
assert.equal(request.connection.servername, 'example-protected.test'); assert.equal(request.connection.hostHeader, 'example-protected.test'); assert.equal(request.connection.rejectUnauthorized, true);
assert.equal(result.schemaVersion, '2.0'); assert.equal(result.targetUrl, url); assert.equal(result.mailDomain, null); assert.equal(result.dns.spf.lookupStatus, 'UNVERIFIED');
console.log('WSC Phase 2C restricted-transport tests: PASS');
